"""
Revue de presse de la DPIEC — app Streamlit
=============================================
Reproduit l'identite visuelle in'li (ruban rose, bandeau teal, logo,
liseret rayures) de la revue Canva actuelle, en remplacant uniquement
la mise en page manuelle : vous deposez vos captures d'ecran, l'app
genere une page HTML moderne consultable et transmissible en un clic.

Lancer l'app :
    pip install streamlit pillow
    streamlit run revue_presse_app.py
"""

import base64
import io
import json
import uuid
from datetime import date, datetime, timedelta
from pathlib import Path

import streamlit as st
from PIL import Image

# --------------------------------------------------------------------------
# Configuration generale
# --------------------------------------------------------------------------

st.set_page_config(page_title="Revue de presse - DPIEC", page_icon="📰", layout="wide")

THEMES_PAR_DEFAUT = [
    "Logement intermédiaire/social",
    "Marché immobilier",
    "Réglementation & politique du logement",
    "Territoires & urbanisme",
    "Autre",
]

MAX_IMAGE_WIDTH = 1000  # px — pour garder un fichier HTML leger

# Logo in'li extrait de la revue existante (fond transparent)
LOGO_INLI_B64 = ""

# --------------------------------------------------------------------------
# Sauvegarde automatique locale (brouillon) — pour ne rien perdre entre deux
# sessions si vous composez la revue sur plusieurs jours
# --------------------------------------------------------------------------

DOSSIER_APP = Path(__file__).resolve().parent
FICHIER_BROUILLON = DOSSIER_APP / "brouillon_revue_dpiec.json"


def charger_brouillon():
    if FICHIER_BROUILLON.exists():
        try:
            with open(FICHIER_BROUILLON, "r", encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return None
    return None


def sauvegarder_brouillon():
    donnees = {
        "articles": st.session_state.articles,
        "themes": st.session_state.themes,
    }
    try:
        with open(FICHIER_BROUILLON, "w", encoding="utf-8") as f:
            json.dump(donnees, f, ensure_ascii=False)
    except Exception:
        pass  # un probleme d'enregistrement ne doit jamais bloquer l'app


if "articles" not in st.session_state or "themes" not in st.session_state:
    _brouillon = charger_brouillon()
    if "articles" not in st.session_state:
        st.session_state.articles = _brouillon["articles"] if _brouillon else []
    if "themes" not in st.session_state:
        st.session_state.themes = _brouillon["themes"] if _brouillon else THEMES_PAR_DEFAUT.copy()

if "editing_id" not in st.session_state:
    st.session_state.editing_id = None


# --------------------------------------------------------------------------
# Publication pour les destinataires — ecrit l'edition dans un dossier partage
# lu par l'app de consultation (revue_presse_consultation.py)
# --------------------------------------------------------------------------

PUBLICATION_DIR = DOSSIER_APP / "revues_publiees"
MANIFEST_PUBLICATION = PUBLICATION_DIR / "manifest.json"


def publier_edition(html_final, titre_revue, numero_edition, sous_titre, date_fin):
    PUBLICATION_DIR.mkdir(exist_ok=True)
    nom_fichier = f"revue_{date_fin.isoformat()}.html"
    chemin = PUBLICATION_DIR / nom_fichier

    with open(chemin, "w", encoding="utf-8") as f:
        f.write(html_final)
    # copie toujours a jour, pratique pour un lien fixe
    with open(PUBLICATION_DIR / "derniere_revue.html", "w", encoding="utf-8") as f:
        f.write(html_final)

    manifest = []
    if MANIFEST_PUBLICATION.exists():
        try:
            with open(MANIFEST_PUBLICATION, "r", encoding="utf-8") as f:
                manifest = json.load(f)
        except Exception:
            manifest = []
    manifest = [m for m in manifest if m.get("fichier") != nom_fichier]
    manifest.append(
        {
            "fichier": nom_fichier,
            "titre": titre_revue,
            "numero": numero_edition,
            "date": sous_titre,
        }
    )
    manifest.sort(key=lambda m: m["fichier"])
    with open(MANIFEST_PUBLICATION, "w", encoding="utf-8") as f:
        json.dump(manifest, f, ensure_ascii=False, indent=2)

    return chemin


# --------------------------------------------------------------------------
# Fonctions utilitaires
# --------------------------------------------------------------------------

def image_to_base64_jpeg(uploaded_file, max_width=MAX_IMAGE_WIDTH, quality=88):
    """Redimensionne et encode une capture d'ecran en base64 (JPEG)."""
    img = Image.open(uploaded_file)
    if img.mode in ("RGBA", "P"):
        img = img.convert("RGB")
    if img.width > max_width:
        ratio = max_width / img.width
        img = img.resize((max_width, int(img.height * ratio)))
    buffer = io.BytesIO()
    img.save(buffer, format="JPEG", quality=quality)
    encoded = base64.b64encode(buffer.getvalue()).decode("utf-8")
    return f"data:image/jpeg;base64,{encoded}"


def deplacer_article(index, direction):
    articles = st.session_state.articles
    nouvel_index = index + direction
    if 0 <= nouvel_index < len(articles):
        articles[index], articles[nouvel_index] = articles[nouvel_index], articles[index]


def supprimer_article(article_id):
    st.session_state.articles = [a for a in st.session_state.articles if a["id"] != article_id]


